export function retryDelay(attempt: number, baseMs: number): number {
  if (attempt <= 0) {
    return 0
  }
  const jitter = Math.random() * 250
  return Math.min(baseMs * 2 ** attempt + jitter, 30_000)
}

export function canRetry(attempt: number): boolean {
  return attempt < 5
}

