#!/usr/bin/env bash
set -euo pipefail

backup_db() {
  local target="$1"
  pg_dump --no-owner "$DATABASE_URL" > "$target"
  gzip -9 -f "$target"
  sha256sum "$target.gz" > "$target.gz.sha256"
}

cleanup_old_backups() {
  find ./backups -name "*.gz" -mtime +14 -delete
}

